    const speakerTag = replyRoleSelect && replyRoleSelect.value ? replyRoleSelect.value : "master";
    const floors = parseFloors(currentBlockText);
    floors.push({ speaker: speakerTag, text: val });
    persistBlockUpdate(serializeFloors(floors), "💬 已追加 " + speakerTag + " 记录", function () {
      if (replyInput) replyInput.value = "";
    });
  }

  if (replyBtn) {
    replyBtn.addEventListener("click", handleAppend);
  }
  if (replyInput) {
    replyInput.addEventListener("keydown", function (e) {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        handleAppend();
      }
    });
  }

  function toggleCollapse() {
