    collapseBtn.textContent = collapsed ? "▸" : "▾";
    collapseBtn.setAttribute("aria-expanded", String(!collapsed));
    notifyFrameResize();
  }

  if (collapseBtn && cardEl) {
    collapseBtn.addEventListener("click", function (ev) {
      ev.stopPropagation();
      toggleCollapse();
    });
  }
  if (headEl && cardEl) {
    headEl.addEventListener("click", toggleCollapse);
  }

  render();

  if (typeof ResizeObserver !== "undefined" && (cardEl || document.body)) {
    new ResizeObserver(notifyFrameResize).observe(cardEl || document.body);
  }
})();
